/**
 * Share cards. Every app, Puffwork pack and bundle has its own paper-and-ink
 * card under /og, generated by scripts/og-cards.mjs; anything without one
 * falls back to the home cover. The build-time metadata pass and the running
 * app both read this, so a shared link and its preview always agree.
 */
import { ASSETS, BUNDLES } from '../data/puffwork.ts'
import { PRODUCTS } from '../data/products.ts'
import { SITE_ORIGIN, normalisePath } from './routes.ts'

export const DEFAULT_SHARE_IMAGE = '/og-cover.jpg'
export const DEFAULT_SHARE_ALT =
  'CensorisLabs — paper and ink sketch of a desk, a small robot and a browser panel'

type ShareCard = { image: string; alt: string }

const appCards = new Map(
  PRODUCTS.map((product): [string, ShareCard] => [
    `/apps/${product.id}`,
    {
      image: `/og/apps/${product.id}.jpg`,
      alt: `${product.name} — paper-and-ink share card with the app name, its category and a sketched numeral`,
    },
  ]),
)

const packCards = new Map(
  ASSETS.map((asset): [string, ShareCard] => [
    `/puffwork/${asset.slug}`,
    {
      image: `/og/puffwork/${asset.slug}.jpg`,
      alt: `${asset.name} — paper-and-ink sketch of the ${asset.material} ${asset.shape} from the Puffwork library`,
    },
  ]),
)

const bundleCards = new Map(
  BUNDLES.map((bundle): [string, ShareCard] => [
    `/puffwork/bundle/${bundle.slug}`,
    {
      image: `/og/puffwork/bundles/${bundle.slug}.jpg`,
      alt: `${bundle.name} — Puffwork bundle share card covering ${bundle.assetSlugs.length} packs`,
    },
  ]),
)

function cardFor(pathname: string): ShareCard | undefined {
  const path = normalisePath(pathname)
  return appCards.get(path) ?? bundleCards.get(path) ?? packCards.get(path)
}

export function shareImageUrl(pathname: string): string {
  return `${SITE_ORIGIN}${cardFor(pathname)?.image ?? DEFAULT_SHARE_IMAGE}`
}

export function shareImageAlt(pathname: string): string {
  return cardFor(pathname)?.alt ?? DEFAULT_SHARE_ALT
}
